query:
SELECT ?citace ?url WHERE {
 GRAPH <esel-esb:eli/czPravniAktZneni> {
  <https://opendata.eselpoint.gov.cz/esel-esb/eli/cz/sb/2006/262/2026-01-01> <https://slovník.gov.cz/datový/sbírka/pojem/má-fragment-znění> ?zf .
 }
 GRAPH <esel-esb:eli/czPravniAktZneniFragment> {
  ?zf <https://slovník.gov.cz/datový/sbírka/pojem/citace-označení-fragmentu-znění-právního-aktu> ?citace ;
      <https://slovník.gov.cz/datový/sbírka/pojem/url-fragmentu-znění> ?url .
  FILTER(STRSTARTS(STR(?url), "/sb/2006/262/2026-01-01#par_1a"))
 }
} ORDER BY ?url
